issue_context.body:
#### Expected Behavior
`Option.SetFilter` rules should be observed.  

#### Actual Behavior
Option chain contains contract with expiry outside `Option.SetFilter` rules.

#### Reproducing the Problem
```csharp
using QuantConnect.Securities.Option;

namespace QuantConnect.Algorithm.CSharp {
    public class CreativeVioletViper : QCAlgorithm {
        private Symbol _symbol;
		
        public override void Initialize() {
            SetStartDate(2020, 3, 1);
            SetEndDate(2020, 4, 30);
            SetCash(100000);

            AddEquity("GOOG");
            var option = AddOption("GOOG");
            option.PriceModel = OptionPriceModels.CrankNicolsonFD();
            option.SetFilter(-30, +30, 0, 7);
            _symbol = option.Symbol;
        }

        public override void OnData(Slice slice) {
            OptionChain chain;
            if (Time.Day > 22 && Time.Minute == 0 &&
                slice.OptionChains.TryGetValue(_symbol, out chain)) {
            	var expiries = chain.Select(x => x.Expiry).Distinct();
            	if (expiries.Any(x => Time > x)) {
            	    var msg = $"{Time} -> " + string.Join(" | ", expires);
            	    Log(msg);
            	}
            }
        }
    }
}
```
